record.field:
# Sync models from all active bifrost providers
providers = env['ai.provider'].search([
    ('provider_type', '=', 'bifrost'),
    ('status', '=', 'confirmed'),
])
for provider in providers:
    try:
        count = provider.action_fetch_models()
        provider.message_post(body=f'Synced {count} models from Bifrost')
    except Exception as e:
        provider.message_post(body=f'Bifrost sync failed: {e}')
